        }
        // Show button only for submitted invoices
        if (frm.doc.docstatus === 1 && !frm.doc.is_return) {
            frm.add_custom_button(__('Unlock for Editing'), function() {
                unlock_invoice_for_editing(frm);
            }, __('Update'));
