});

function unlock_invoice_for_editing(frm) {
    frappe.confirm(
        __('This will unlock the invoice for editing. You can then modify rates, items, or any other details. After making changes, click Submit again.<br><br><b>Continue?</b>'),
        function() {
            frappe.dom.freeze(__('Unlocking invoice...'));

            frappe.call({
                method: 'erpnext.accounts.doctype.sales_invoice.sales_invoice.unlock_sales_invoice',
                args: {
                    invoice_name: frm.doc.name
                },
                callback: function(r) {
                    frappe.dom.unfreeze();

                    if (r.message && r.message.success) {
                        frappe.show_alert({
                            message: __('Invoice unlocked! You can now edit and resubmit.'),
                            indicator: 'green'
                        }, 5);

                        // Reload the form as draft
                        setTimeout(function() {
                            frm.reload_doc();
                        }, 1000);
                    } else {
                        frappe.msgprint({
                            title: __('Error'),
                            message: r.message ? r.message.error : 'Failed to unlock invoice',
                            indicator: 'red'
                        });
                    }
                }
            });
        }
    );
}

