});

frappe.ui.form.on("Sales Order", {
    freight: function (frm) {
    let freight = frm.doc.freight || 0;

    // Find existing FREIGHT row
    let existing = (frm.doc.items || []).find(d => d.item_code === "FREIGHT");

    if (freight > 0) {
        if (existing) {
            // Update existing row
            existing.rate = freight;
            existing.qty = 1;
            existing.amount = freight;
        } else {
            // Add new FREIGHT row
            let row = frm.add_child("items");
            row.item_code = "FREIGHT";
            row.item_name = "Freight Charges";
            row.qty = 1;
            row.rate = freight;
            row.amount = freight;
            row.uom = "Nos"; // or Service UOM
        }
    } else {
        // Remove FREIGHT row if freight = 0
        frm.doc.items = frm.doc.items.filter(d => d.item_code !== "FREIGHT");
    }

    frm.refresh_field("items");
    frm.script_manager.trigger("calculate_taxes_and_totals");
    }
});

