// Client Script — Sales Invoice (Form)
// Creates a simplified "Quick Credit Note" dialog
// Target: ERPNext v15

frappe.ui.form.on('Sales Invoice', {

	refresh: function(frm) {
		if (frm.doc.docstatus === 1 && !frm.doc.is_return) {
			frm.add_custom_button(__('Quick Credit Note'), function() {
				gj_open_credit_note_dialog(frm);
			}, __('Create'));
		}
	}

});

// ── Dialog ────────────────────────────────────────────────────
function gj_open_credit_note_dialog(frm) {

	var d = new frappe.ui.Dialog({
		title: '📋 Quick Credit Note — ' + frm.doc.customer,
		size: 'small',
		fields: [
			{
				fieldtype: 'Link', fieldname: 'customer', label: 'Customer',
				options: 'Customer', default: frm.doc.customer, read_only: 1, reqd: 1
			},
			{
				fieldtype: 'Link', fieldname: 'return_against', label: 'Against Sales Invoice',
				options: 'Sales Invoice', default: frm.doc.name, read_only: 1, reqd: 1,
				description: 'Credit Note will be linked to this invoice'
			},
			{
				fieldtype: 'Date', fieldname: 'posting_date', label: 'Posting Date',
				default: frappe.datetime.get_today(), reqd: 1
			},
			{ fieldtype: 'Section Break' },
			{
				fieldtype: 'Currency', fieldname: 'credit_amount',
				label: 'Credit Amount (excluding GST)', reqd: 1,
				description: 'Enter base amount. GST will be auto-calculated.'
			},
			{
				fieldtype: 'Select', fieldname: 'tax_template',
				label: 'GST Tax Template', options: '', reqd: 1
			},
			{ fieldtype: 'Column Break' },
			{
				fieldtype: 'HTML', fieldname: 'tax_preview', label: '',
				options: '<div id="gj-cn-preview" style="background:#f8faff;border:1px solid #dbeafe;'
					+ 'border-radius:10px;padding:14px;font-size:12.5px;color:#1a2340;min-height:80px;">'
					+ '<span style="color:#6b7a99">Enter amount to see GST preview</span></div>'
			},
			{ fieldtype: 'Section Break' },
			{
				fieldtype: 'Small Text', fieldname: 'reason',
				label: 'Reason / Narration', reqd: 1,
				placeholder: 'e.g. Rate difference on Invoice ' + frm.doc.name
			}
		],
		primary_action_label: 'Create Credit Note',
		primary_action: function(values) {
			if (d._submitting) return;
			d._submitting = true;
			gj_create_credit_note(frm, values, d);
		}
	});

	// Load tax templates — pre-select from original invoice
	frappe.db.get_list('Sales Taxes and Charges Template', {
		filters: [['disabled', '=', 0]], fields: ['name'], limit: 50
	}).then(function(templates) {
		var opts = templates.map(function(t) { return t.name; }).join('\n');
		d.set_df_property('tax_template', 'options', opts);
		d.set_value('tax_template', frm.doc.taxes_and_charges || '');
		update_preview(d);
	});

	d.fields_dict['credit_amount'].df.onchange = function() { update_preview(d); };
	d.fields_dict['tax_template'].df.onchange  = function() { update_preview(d); };

	d.show();
}

// ── Live GST Preview ──────────────────────────────────────────
function update_preview(d) {
	var amount   = flt(d.get_value('credit_amount'));
	var template = d.get_value('tax_template');

	if (!amount || !template) {
		$('#gj-cn-preview').html('<span style="color:#6b7a99">Enter amount to see GST preview</span>');
		return;
	}

	frappe.db.get_list('Sales Taxes and Charges', {
		filters: [['parent', '=', template]],
		fields: ['description', 'rate', 'account_head'],
		limit: 10
	}).then(function(taxes) {
		var total_tax = 0;
		var rows = taxes.map(function(t) {
			var tax_amt = flt((amount * t.rate) / 100, 2);
			total_tax += tax_amt;
			return '<tr>'
				+ '<td style="padding:4px 8px;color:#374151">' + (t.account_head || t.description || '') + '</td>'
				+ '<td style="padding:4px 8px;text-align:right">' + t.rate + '%</td>'
				+ '<td style="padding:4px 8px;font-weight:700;color:#1d4ed8;text-align:right">₹' + fmt_cur(tax_amt) + '</td>'
				+ '</tr>';
		}).join('');

		$('#gj-cn-preview').html(
			'<table style="width:100%;border-collapse:collapse">'
			+ '<tr style="border-bottom:1px solid #e2e8f4">'
			+ '<td style="padding:4px 8px;color:#6b7a99">Base Amount</td>'
			+ '<td colspan="2" style="padding:4px 8px;font-weight:700;text-align:right">₹' + fmt_cur(amount) + '</td>'
			+ '</tr>'
			+ rows
			+ '<tr style="border-top:2px solid #dbeafe;background:#eff6ff">'
			+ '<td style="padding:6px 8px;font-weight:800;color:#1a2340">Total Credit Note</td>'
			+ '<td colspan="2" style="padding:6px 8px;font-weight:800;color:#16a34a;font-size:14px;text-align:right">₹'
			+ fmt_cur(flt(amount + total_tax, 2)) + '</td>'
			+ '</tr></table>'
		);
	});
}

