// ── Create Credit Note ────────────────────────────────────────
function gj_create_credit_note(frm, values, dialog) {

	if (flt(values.credit_amount) <= 0) {
		frappe.msgprint({ title: 'Invalid Amount', message: 'Amount must be greater than zero.', indicator: 'red' });
		return;
	}

	dialog.disable_primary_action();
	frappe.show_progress('Creating Credit Note...', 0, 100);

	// Fetch full original invoice — gets all mandatory fields + taxes in one call
	frappe.db.get_doc('Sales Invoice', values.return_against).then(function(orig) {

		frappe.show_progress('Creating Credit Note...', 40, 100);

		// Copy taxes directly from original invoice rows
		// account_head, description, charge_type all come intact — no template re-fetch needed
		var taxes_rows = (orig.taxes || []).map(function(t) {
			return {
				charge_type:            t.charge_type,
				account_head:           t.account_head,
				rate:                   t.rate,
				description:            t.description,
				cost_center:            t.cost_center || orig.cost_center,
				included_in_print_rate: t.included_in_print_rate || 0
			};
		});

		// Build credit note copying every mandatory field from original invoice
		var credit_note = {
			doctype:             'Sales Invoice',
			is_return:           1,
			return_against:      values.return_against,
			customer:            orig.customer,
			posting_date:        values.posting_date,
			company:             orig.company,
			currency:            orig.currency,
			conversion_rate:     orig.conversion_rate || 1,
			taxes_and_charges:   orig.taxes_and_charges,
			remarks:             values.reason,
			debit_to:            orig.debit_to,
			selling_price_list:  orig.selling_price_list,
			price_list_currency: orig.price_list_currency,
			plc_conversion_rate: orig.plc_conversion_rate || 1,
			cost_center:         orig.cost_center,
			territory:           orig.territory,
			customer_address:    orig.customer_address,
			contact_person:      orig.contact_person,
			tc_name:             orig.tc_name,
			delivery_challan:    orig.delivery_challan || '',
			taxes:               taxes_rows,
			items: [{
				item_code:      'CR ADJUST',
				item_name:      'RATE DIFFERENCE',
				description:    values.reason,
				qty:            -1,
				rate:           flt(values.credit_amount),
				uom:            'Nos',
				income_account: orig.items[0] ? orig.items[0].income_account : '',
				cost_center:    orig.items[0] ? orig.items[0].cost_center : '',
				warehouse:      orig.items[0] ? orig.items[0].warehouse : ''
			}]
		};

		// Save
		frappe.call({
			method: 'frappe.client.insert',
			args: { doc: credit_note },
			callback: function(r) {
				frappe.show_progress('Creating Credit Note...', 80, 100);

				if (r.exc || !r.message) {
					frappe.show_progress('', 0, 100);
					dialog.enable_primary_action();
					frappe.msgprint({
						title: 'Error',
						message: 'Could not save Credit Note. Check console for details.',
						indicator: 'red'
					});
					return;
				}

				var cn_name = r.message.name;

				// Submit
				frappe.call({
					method: 'frappe.client.submit',
					args: { doc: r.message },
					callback: function(sr) {
						frappe.show_progress('', 100, 100);
						dialog.hide();

						if (sr.exc) {
							frappe.msgprint({
								title: 'Saved but not submitted',
								message: 'Credit Note <b>' + cn_name + '</b> saved as Draft. Please submit manually.',
								indicator: 'orange'
							});
							frappe.set_route('Form', 'Sales Invoice', cn_name);
							return;
						}

						frappe.show_alert({
							message: '✅ Credit Note <b>' + cn_name + '</b> created and submitted',
							indicator: 'green'
						}, 6);


					}
				});
			}
		});
	});
}

